/* 
 * Effet de mur crème/ciment "retro" 
 *  - Autorise l'ajustement de paramètres pour contrôler la couleur de base,
 *    l'intensité du bruit, l'échelle, etc.
 *  - Ne repose sur aucune texture importée, uniquement du "noise" procédural.
 *  - Inspiré de la description : "Close Up retro plain cream color cement wall."
 *
 * Vous pouvez modifier les #define pour ajuster le rendu.
 */

#ifdef GL_ES
precision mediump float;
#endif

// =========================================================
// --- PARAMÈTRES À MODIFIER SELON VOS BESOINS -------------
// =========================================================

// Couleur de base du mur (teinte crème)
#define BASE_COLOR      vec3(0.97, 0.94, 0.88)

// Intensité du contraste du bruit (augmentation diminue la “platitude”)
#define NOISE_INTENSITY 0.25

// Fréquence principale du bruit (plus grand = motif plus serré)
#define NOISE_SCALE     8.0

// Nombre d’octaves de FBM (influe sur la richesse du motif)
#define OCTAVES         5

// Force du “warping” (déformation / effet de plâtre)
#define WARP_STRENGTH   0.25

// Échelle du warping (plus grand = motifs de déformation plus larges)
#define WARP_SCALE      1.5

// =========================================================
// --- FONCTIONS DE BRUIT / FBM ----------------------------
// =========================================================

// Hash basique pour générer un pseudo-aléatoire à partir de (x,y)
float hash12(vec2 p) {
    // Simple fonction de hash basée sur une suite pseudo-aléatoire
    float h = dot(p, vec2(127.1, 311.7));
    return fract(sin(h) * 43758.5453);
}

// Noise bilinéaire sur grille
float noise2D(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);

    // 4 coins autour du point
    float a = hash12(i + vec2(0.0, 0.0));
    float b = hash12(i + vec2(1.0, 0.0));
    float c = hash12(i + vec2(0.0, 1.0));
    float d = hash12(i + vec2(1.0, 1.0));

    // Interpolation (fade)
    vec2 u = f * f * (3.0 - 2.0 * f);

    // Mix bilinéaire
    return mix(
        mix(a, b, u.x),
        mix(c, d, u.x),
        u.y
    );
}

// FBM (Fractional Brownian Motion) basique
float fbm(vec2 p) {
    float result = 0.0;
    float amp    = 0.5;
    for(int i = 0; i < OCTAVES; i++) {
        result += amp * noise2D(p);
        p      *= 2.01;  // On peut jouer légèrement sur ce facteur
        amp    *= 0.5;
    }
    return result;
}

// =========================================================
// --- MAIN SHADER -----------------------------------------
// =========================================================
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // Coordonnées UV normalisées [0,1]
    vec2 uv = fragCoord.xy / iResolution.xy;

    // Ajuster le ratio si besoin pour éviter la déformation
    uv.x *= iResolution.x / iResolution.y;

    // Première passe de FBM pour créer une déformation (warping)
    // On veut donner un aspect "plâtre" un peu marbré
    float warp = fbm(uv * WARP_SCALE + iTime * 0.2) * WARP_STRENGTH;

    // On décale légèrement les coordonnées avec ce "warp"
    uv += vec2(warp, warp * 0.5);

    // Récupération du bruit principal
    float n = fbm(uv * NOISE_SCALE);

    // On centre autour de 0.0 => (n - 0.5) pour pouvoir renforcer/diminuer
    n = (n - 0.5) * NOISE_INTENSITY;

    // Couleur de base (mur crème) + variation
    vec3 color = BASE_COLOR + vec3(n);

    // Sortie du shader
    fragColor = vec4(color, 1.0);
}
